//! Strict, bounded child pipe messages with an invocation ID independent of the ticket.
use super::{MAX_FRAME_BYTES, SpaceMethod};
use crate::Error;
use calternal_types::ErrorCode;
use serde::{Deserialize, Serialize};
use serde_json::Value;
use uuid::Uuid;

/// One frame on the supervisor's private package pipe.
#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ChildFrame {
    protocol_version: u8,
    /// Local invocation correlation, regenerated by the supervisor.
    pub invocation_id: Uuid,
    /// Only capability-free child payloads cross this pipe.
    pub message: ChildMessage,
}

/// The pipe side of one read-only invocation.
#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case", deny_unknown_fields)]
pub enum ChildMessage {
    /// Supervisor starts an admitted call.
    Invoke {
        /// Approved operation identifier.
        operation: String,
        /// Author input with no space or authority fields.
        input: Value,
    },
    /// Package requests an engine operation.
    HostCall {
        /// Callback correlation within the invocation.
        call_id: Uuid,
        /// Requested engine method.
        method: SpaceMethod,
        /// Method-specific input checked by the host.
        input: Value,
    },
    /// Host result correlated with the original callback.
    HostReply {
        /// Callback correlation.
        call_id: Uuid,
        /// Bounded engine result or stable refusal code.
        result: Result<Value, ErrorCode>,
    },
    /// Package resolves the invocation.
    Complete {
        /// Author output.
        data: Value,
    },
    /// Package fails the invocation without disclosing details.
    Failed {},
    /// Supervisor cancels the specified local invocation.
    Cancel {},
}

impl ChildFrame {
    /// Serialize a bounded supervisor frame. Cost: one bounded allocation.
    pub fn encode(invocation_id: Uuid, message: ChildMessage) -> Result<Vec<u8>, Error> {
        if invocation_id.is_nil() {
            return Err(Error::Invalid);
        }
        let mut line = crate::bounded::json(
            &Self {
                protocol_version: 2,
                invocation_id,
                message,
            },
            MAX_FRAME_BYTES,
        )?;
        line.push(b'\n');
        Ok(line)
    }

    /// Parse a bounded frame from the package, checking direction before routing.
    /// Cost: one strict JSON parse. The caller must cap buffering before parse.
    pub fn decode(line: &[u8]) -> Result<Self, Error> {
        if line.len() > MAX_FRAME_BYTES + 1 {
            return Err(Error::TooLarge);
        }
        let frame: Self = super::parse(line)?;
        if frame.protocol_version != 2 || frame.invocation_id.is_nil() {
            return Err(Error::Invalid);
        }
        match &frame.message {
            ChildMessage::HostCall { call_id, .. } if !call_id.is_nil() => Ok(frame),
            ChildMessage::Complete { .. } | ChildMessage::Failed {} => Ok(frame),
            _ => Err(Error::Invalid),
        }
    }
}
